SELECT 
FROM itinerary_stops
WHERE trip_id = #{tripId}
  AND day_number = #{dayNumber}
ORDER BY sort_order ASC, id ASC

SELECT 
FROM itinerary_stops
WHERE id = #{id}
  AND trip_id = #{tripId}
  AND day_number = #{dayNumber}

SELECT COALESCE(MAX(sort_order), 0)
FROM itinerary_stops
WHERE trip_id = #{tripId}
  AND day_number = #{dayNumber}

mapper.update:
UPDATE itinerary_stops
SET selected_time = #{selectedTime},
    memo = #{memo},
    transport = #{transport}
WHERE id = #{id}
  AND trip_id = #{tripId}
  AND day_number = #{dayNumber}

mapper.delete:
DELETE FROM itinerary_stops
WHERE id = #{id}
  AND trip_id = #{tripId}
  AND day_number = #{dayNumber}

mapper.update:
UPDATE itinerary_stops
SET sort_order = sort_order - 1
WHERE trip_id = #{tripId}
  AND day_number = #{dayNumber}
  AND sort_order > #{sortOrder}

UPDATE itinerary_stops
SET sort_order = sort_order + #{offset}
WHERE trip_id = #{tripId}
  AND day_number = #{dayNumber}

UPDATE itinerary_stops
SET sort_order = #{sortOrder}
WHERE id = #{id}
  AND trip_id = #{tripId}
  AND day_number = #{dayNumber}
